                tempExpression = tempExpression.replace(regex, `(${value})`);
            } else if (value === '') {
                 // Treat empty cells as 0 in arithmetic context
                tempExpression = tempExpression.replace(regex, '(0)');
            } else {
                // If it's text or error, treat as 0 for calculation safety
                tempExpression = tempExpression.replace(regex, '(0)');
