function handleColumnHeaderClick(e) {
    const header = e.target.closest('.col-header'); // Find the parent header element
    if (!header) return; 

    const colIdx = COLUMNS.indexOf(header.dataset.col);

    // --- Color Change ---
    if (e.target.classList.contains('color-picker')) {
        const color = e.target.value;
        for (let r = 1; r <= NUM_ROWS; r++) {
            const key = getCellKey(colIdx, r);
            // Only update background if the color is different from current style
            if (spreadsheetData[key].style.backgroundColor !== color) {
                spreadsheetData[key].style.backgroundColor = color;
                updateCellDOM(key, spreadsheetData[key]);
            }
        }
        saveState();
    }

    // --- Delete Column ---
    if (e.target.dataset.action === 'delete') {
        if (!confirm(`¿Está seguro de que desea borrar la columna ${header.textContent}? Esta acción es irreversible.`)) return;

        // 1. Clear data and remove DOM elements for all cells in this column
        for (let r = 1; r <= NUM_ROWS; r++) {
            const key = getCellKey(colIdx, r);
            spreadsheetData[key].rawInput = '';
            spreadsheetData[key].value = '';
            // Preserve formatting styles when clearing content/data
            // We only reset the data state, not the visual style.
            updateCellDOM(key, spreadsheetData[key]); 
        }

        // 2. Remove DOM elements (The actual column cells)
        const colCells = document.querySelectorAll(`.col-header[data-col="${header.dataset.col}"] + .row > .spreadsheet-cell`);
        colCells.forEach(cell => cell.remove());

        // 3. Update the header structure (Remove the letter div itself)
        header.remove();

        // 4. Re-index and re-run calculations for remaining cells
        saveState();
    }

    // --- Clear Content Column ---
    if (e.target.dataset.action === 'clear') {
        for (let r = 1; r <= NUM_ROWS; r++) {
            const key = getCellKey(colIdx, r);
            spreadsheetData[key].rawInput = '';
            spreadsheetData[key].value = '';
            // IMPORTANT: Do NOT reset style here, otherwise background colors are lost.
            updateCellDOM(key, spreadsheetData[key]);
        }
        saveState();
    }

    // --- Hide Column ---
    if (e.target.dataset.action === 'hide') {
        const colHeaderElement = header;
        colHeaderElement.classList.add('hidden-col'); // Use class for hiding
        document.querySelectorAll(`.spreadsheet-cell[data-col="${header.dataset.col}"]`).forEach(el => el.classList.add('hidden-col'));
        saveState();
    } else {
         // Show all elements if not explicitly hiding/deleting
        const colHeaderElement = header;
        colHeaderElement.classList.remove('hidden-col'); // Use class for showing
        document.querySelectorAll(`.spreadsheet-cell[data-col="${header.dataset.col}"]`).forEach(el => el.classList.remove('hidden-col'));
    }
}
